import{_ as r,C as n,o as s,c as o,a2 as t,E as i}from"./chunks/framework.CBxkvBm_.js";const b=JSON.parse('{"title":"Linear Memory Structures & Indexing","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/linear-memory-structures.md","filePath":"algorithms/linear-memory-structures.md"}'),l={name:"algorithms/linear-memory-structures.md"};function d(c,e,p,g,m,u){const a=n("MermaidBlock");return s(),o("div",null,[e[0]||(e[0]=t('<h1 id="linear-memory-structures-indexing" tabindex="-1">Linear Memory Structures &amp; Indexing <a class="header-anchor" href="#linear-memory-structures-indexing" aria-label="Permalink to &quot;Linear Memory Structures &amp; Indexing&quot;">​</a></h1><p><strong>Implementation</strong>:</p><ul><li>Roaring Bitmaps: <code>RoaringBitmap</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/core/roaring.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/core/roaring.ts</code></a></li><li>Front-Coded IRI Dictionary: <code>FrontCodedDictionary</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/core/trie.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/core/trie.ts</code></a></li><li>Slotted Page B+ Tree: <code>PagedBTree</code> in <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/wasm/storage/paged_btree.ts" target="_blank" rel="noreferrer"><code>packages/runtime/src/wasm/storage/paged_btree.ts</code></a></li></ul><hr><h2 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h2><h3 id="compressed-roaring-bitmaps" tabindex="-1">Compressed Roaring Bitmaps <a class="header-anchor" href="#compressed-roaring-bitmaps" aria-label="Permalink to &quot;Compressed Roaring Bitmaps&quot;">​</a></h3><ul><li><strong>Chambi, S., Lemire, D., Kaser, O., &amp; Godin, R. (2016)</strong>. <em>&quot;Better bitmap performance with Roaring bitmaps.&quot;</em><br><strong>Software: Practice and Experience</strong>, 46(5), pp. 709–719.<br> DOI: <a href="https://doi.org/10.1002/spe.2325" target="_blank" rel="noreferrer">10.1002/spe.2325</a></li><li><strong>Lemire, D., Ssi-Yan-Kai, G., &amp; Kaser, O. (2018)</strong>. <em>&quot;Consistently faster and smaller compressed bitmaps with Roaring.&quot;</em><br><strong>Software: Practice and Experience</strong>, 48(9), pp. 1615–1638.<br> DOI: <a href="https://doi.org/10.1002/spe.2560" target="_blank" rel="noreferrer">10.1002/spe.2560</a></li></ul><h3 id="front-coded-string-iri-compression" tabindex="-1">Front-Coded String &amp; IRI Compression <a class="header-anchor" href="#front-coded-string-iri-compression" aria-label="Permalink to &quot;Front-Coded String &amp; IRI Compression&quot;">​</a></h3><ul><li><strong>Witten, I. H., Moffat, A., &amp; Bell, T. C. (1999)</strong>. <em>Managing Gigabytes: Compressing and Indexing Documents and Images</em> (2nd ed.). Morgan Kaufmann.<br> ISBN: <a href="https://dl.acm.org/doi/book/10.5555/553876" target="_blank" rel="noreferrer">1-55860-570-3</a></li><li><strong>Martínez-Prieto, M. A., Fernández, J. D., &amp; Cánovas, R. (2012)</strong>. <em>&quot;Compression of RDF Dictionaries.&quot;</em><br><strong>ACM Transactions on the Web (TWEB)</strong>, 6(4), pp. 1–35.<br> DOI: <a href="https://doi.org/10.1145/2382636.2382639" target="_blank" rel="noreferrer">10.1145/2382636.2382639</a></li><li><strong>Brisaboa, N. R., Cánovas, R., Francisco, C. C., Martínez-Prieto, M. A., &amp; Navarro, G. (2011)</strong>. <em>&quot;K2-trees for compact Web graph representation.&quot;</em><br><strong>Information Systems</strong>, 39, pp. 152–163.<br> DOI: <a href="https://doi.org/10.1016/j.is.2012.08.003" target="_blank" rel="noreferrer">10.1016/j.is.2012.08.003</a></li></ul><h3 id="slotted-page-b-tree-spo-triple-storage" tabindex="-1">Slotted Page B+ Tree &amp; SPO Triple Storage <a class="header-anchor" href="#slotted-page-b-tree-spo-triple-storage" aria-label="Permalink to &quot;Slotted Page B+ Tree &amp; SPO Triple Storage&quot;">​</a></h3><ul><li><strong>Bayer, R., &amp; McCreight, E. (1972)</strong>. <em>&quot;Organization and maintenance of large ordered indexes.&quot;</em><br><strong>Acta Informatica</strong>, 1(3), pp. 173–189.<br> DOI: <a href="https://doi.org/10.1007/BF00288683" target="_blank" rel="noreferrer">10.1007/BF00288683</a></li><li><strong>Comer, D. (1979)</strong>. <em>&quot;The ubiquitous B-tree.&quot;</em><br><strong>ACM Computing Surveys</strong>, 11(2), pp. 121–137.<br> DOI: <a href="https://doi.org/10.1145/356770.356776" target="_blank" rel="noreferrer">10.1145/356770.356776</a></li><li><strong>Mohan, C., Haderle, D., Lindsay, B., Pirahesh, H., &amp; Schwarz, P. (1992)</strong>. <em>&quot;ARIES: A transaction recovery method supporting fine-granularity locking and partial rollbacks using write-ahead logging.&quot;</em><br><strong>ACM Transactions on Database Systems</strong>, 17(1), pp. 94–162.<br> DOI: <a href="https://doi.org/10.1145/128765.128770" target="_blank" rel="noreferrer">10.1145/128765.128770</a></li><li><strong>Neumann, T., &amp; Weikum, G. (2008)</strong>. <em>&quot;RDF-3X: A RISC-style engine for RDF.&quot;</em><br><strong>Proceedings of the VLDB Endowment</strong>, 1(1), pp. 647–659.<br> DOI: <a href="https://doi.org/10.14778/1453856.1453927" target="_blank" rel="noreferrer">10.14778/1453856.1453927</a></li></ul><hr><h2 id="modelscript-architectural-rationale" tabindex="-1">ModelScript Architectural Rationale <a class="header-anchor" href="#modelscript-architectural-rationale" aria-label="Permalink to &quot;ModelScript Architectural Rationale&quot;">​</a></h2><p>ModelScript compiles and indexes multi-million-element engineering workspaces, including the complete Modelica Standard Library (MSL), SysML v2 standard libraries (KerML), ISO 10303 STEP schemata, and OWL2 domain ontologies.</p><p>Representing these vast semantic graphs using standard JavaScript object heaps incurs:</p><ul><li>Extreme memory bloat (JavaScript objects typically consume 40–80 bytes of overhead per node).</li><li>Heavy Garbage Collector (GC) pressure and unpredictable pause times during interactive IDE editing.</li><li>Slow pointer chasing across cache lines.</li></ul><p>To solve this, ModelScript implements <strong>compact, zero-GC data structures</strong> operating directly inside WebAssembly 64-bit linear memory.</p><hr><h2 id="architecture-of-core-wasm-structures" tabindex="-1">Architecture of Core WASM Structures <a class="header-anchor" href="#architecture-of-core-wasm-structures" aria-label="Permalink to &quot;Architecture of Core WASM Structures&quot;">​</a></h2>',19)),i(a,{code:"flowchart%20TD%0A%20%20%20%20WORKSPACE%5B%22Workspace%20Indexer%20%26%20AST%20Symbols%22%5D%20--%3E%20ROARING%5B%22Roaring%20Bitmaps%3Cbr%2F%3E12-byte%20Chunk%20Descriptors%3Cbr%2F%3EArray%20%2F%20Dense%20Bitset%22%5D%0A%20%20%20%20WORKSPACE%20--%3E%20TRIE%5B%22Front-Coded%20Dictionary%3Cbr%2F%3EShared%20Prefixes%20(8-entry%20blocks)%3Cbr%2F%3E%2B%20Robin%20Hood%20Hash%20Map%22%5D%0A%20%20%20%20WORKSPACE%20--%3E%20BTREE%5B%22Paged%20B%2B%20Tree%20(4KB%20Slotted%20Pages)%3Cbr%2F%3ESubject-Predicate-Object%20(SPO)%3Cbr%2F%3EPredicate-Object-Subject%20(POS)%22%5D%0A%20%20%20%20ROARING%20--%3E%20SALSA%5B%22Salsa%20Query%20Dependency%20Tracking%22%5D%0A%20%20%20%20TRIE%20--%3E%20INTERN%5B%22Symbol%20%26%20IRI%20ID%20Interning%22%5D%0A%20%20%20%20BTREE%20--%3E%20SPARQL%5B%22WCOJ%20Pattern%20Matching%20%26%20SPARQL%20Engine%22%5D%0A"}),e[1]||(e[1]=t(`<h3 id="_1-unmanaged-roaring-bitmaps" tabindex="-1">1. Unmanaged Roaring Bitmaps <a class="header-anchor" href="#_1-unmanaged-roaring-bitmaps" aria-label="Permalink to &quot;1. Unmanaged Roaring Bitmaps&quot;">​</a></h3><p>Partitions the 32-bit integer space into $2^{16} = 65{,}536$ chunks based on the upper 16 bits:</p><ul><li><strong>12-Byte Chunk Descriptor</strong>:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Offset 0..3:   [key: u16] | [containerType: u16]</span></span>
<span class="line"><span>Offset 4..7:   [containerPtr: u32]</span></span>
<span class="line"><span>Offset 8..9:   [cardinality: u16]</span></span>
<span class="line"><span>Offset 10..11: [capacity: u16]</span></span></code></pre></div></li><li><strong>Adaptive Containers</strong>: <ul><li><strong>Array Container</strong>: Used when cardinality $&lt; 4{,}096$. Elements are stored as sorted <code>u16</code> integers in linear memory.</li><li><strong>Bitmap Container</strong>: When cardinality reaches $4{,}096$, the container automatically converts to a dense 8,192-byte bitset ($1{,}024 \\times \\text{u64}$ words), allowing bitwise <code>AND</code>, <code>OR</code>, <code>XOR</code> operations at hardware SIMD speeds.</li></ul></li></ul><h3 id="_2-front-coded-string-iri-dictionary" tabindex="-1">2. Front-Coded String &amp; IRI Dictionary <a class="header-anchor" href="#_2-front-coded-string-iri-dictionary" aria-label="Permalink to &quot;2. Front-Coded String &amp; IRI Dictionary&quot;">​</a></h3><p>Engineering identifiers and semantic URIs often share massive common prefixes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://modelscript.io/sysml2/core#PartDefinition</span></span>
<span class="line"><span>http://modelscript.io/sysml2/core#ItemDefinition</span></span>
<span class="line"><span>http://modelscript.io/sysml2/core#ActionDefinition</span></span></code></pre></div><p>The front-coded dictionary partitions sorted strings into blocks of size $K = 8$:</p><ul><li><strong>Header String</strong>: Stored uncompressed at the beginning of each block.</li><li><strong>Suffix Entries</strong>: Encoded as <code>[commonPrefixLen: u8, suffixLen: u8, suffixBytes]</code>.</li><li><strong>Hybrid Lookups</strong>: Combines front-coding (achieving 75–85% memory compression) with a zero-cost 64-bit Robin Hood hash map (<code>UnmanagedMap64</code>) for $O(1)$ string-to-ID interning.</li></ul><h3 id="_3-paged-4kb-slotted-b-tree" tabindex="-1">3. Paged 4KB Slotted B+ Tree <a class="header-anchor" href="#_3-paged-4kb-slotted-b-tree" aria-label="Permalink to &quot;3. Paged 4KB Slotted B+ Tree&quot;">​</a></h3><p>Stores billions of semantic assertions and relational tuples:</p><ul><li><strong>4KB Slotted Page Layout (32-byte header + 254 entries)</strong>:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[0..3]   pageId: u32</span></span>
<span class="line"><span>[4..5]   pageType: u16 (1 = Leaf, 2 = Internal)</span></span>
<span class="line"><span>[6..7]   itemCount: u16</span></span>
<span class="line"><span>[8..11]  prevPage: u32 (doubly-linked leaf chain for range scans)</span></span>
<span class="line"><span>[12..15] nextPage: u32</span></span>
<span class="line"><span>[16..19] parentPage: u32</span></span>
<span class="line"><span>[20..23] flags: u32</span></span>
<span class="line"><span>[24..31] lsn: u64 (Log Sequence Number for crash consistency)</span></span></code></pre></div></li><li><strong>RDF-3X Triples</strong>: Triples $(S, P, O)$ are indexed in clustered B+ tree leaf chains. Full index permutations (<code>SPO</code>, <code>POS</code>, <code>OSP</code>) permit fast range scans for multi-way graph joins without intermediate hash joins.</li></ul><hr><h2 id="upstream-downstream-integration" tabindex="-1">Upstream &amp; Downstream Integration <a class="header-anchor" href="#upstream-downstream-integration" aria-label="Permalink to &quot;Upstream &amp; Downstream Integration&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Data Structure</th><th style="text-align:left;">Upstream Dependencies</th><th style="text-align:left;">Downstream Consumers</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>RoaringBitmap</strong></td><td style="text-align:left;">Symbol IDs from <code>SymbolIndexer</code></td><td style="text-align:left;">Invalidation sets in <code>QueryEngine</code>, type sets</td></tr><tr><td style="text-align:left;"><strong>FrontCodedDictionary</strong></td><td style="text-align:left;">AST string literals, Qualified names, URIs</td><td style="text-align:left;">Inter-file symbol resolution, memory-mapped LSP indexing</td></tr><tr><td style="text-align:left;"><strong>PagedBTree</strong></td><td style="text-align:left;">AST semantic relationships, OWL2 axioms</td><td style="text-align:left;">Leapfrog Triejoin (WCOJ), graph query evaluators, SPARQL</td></tr></tbody></table>`,14))])}const f=r(l,[["render",d]]);export{b as __pageData,f as default};
